import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Install MeetCue","description":"","frontmatter":{},"headers":[],"relativePath":"install.md","filePath":"install.md","lastUpdated":1793314357000}'),n={name:"install.md"};function o(l,e,r,p,d,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="install-meetcue" tabindex="-1">Install MeetCue <a class="header-anchor" href="#install-meetcue" aria-label="Permalink to &quot;Install MeetCue&quot;">​</a></h1><p>This page shows how to install, update and remove MeetCue on Windows and macOS. The whole process works without administrator rights.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Windows 10 version 2004 or later / Windows 11 (64-bit), or macOS 13 or later (Apple Silicon or Intel).</li><li>On Windows, the Microsoft Edge WebView2 runtime. It is already installed on almost every Windows 10 and 11 computer. If MeetCue reports <a href="/meetcue/troubleshooting/error-codes#mc-sys-001">MC-SYS-001</a>, install the Evergreen runtime from Microsoft.</li><li>An API key for a speech recognition provider and one for a language model provider. See <a href="/meetcue/guide/providers">Providers and keys</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">Linux</p><p>MeetCue builds on Linux, but its native audio capture backend is not implemented yet.</p></div><h2 id="install-on-macos" tabindex="-1">Install on macOS <a class="header-anchor" href="#install-on-macos" aria-label="Permalink to &quot;Install on macOS&quot;">​</a></h2><p>Requires macOS 13 Ventura or later, on Apple Silicon or Intel. Download <code>meetcue-macos-arm64.dmg</code> (Apple Silicon) or <code>meetcue-macos-x64.dmg</code> (Intel) from <a href="https://github.com/Amazingkenneth/meetcue/releases" target="_blank" rel="noreferrer">Releases</a>, open it and drag <strong>MeetCue.app</strong> to <strong>Applications</strong>. CI also provides app ZIPs on pull requests for testing before a release.</p><p>The current Mac packages are ad-hoc signed and are not notarized. If macOS blocks an app you downloaded from this repository, open <strong>System Settings › Privacy &amp; Security</strong> and choose <strong>Open Anyway</strong> for MeetCue. Do not disable Gatekeeper globally.</p><p>On first use, allow <strong>Microphone</strong> and <strong>Screen &amp; System Audio Recording</strong> (called <strong>Screen Recording</strong> on older macOS) in <strong>System Settings › Privacy &amp; Security</strong>. Quit and reopen MeetCue after granting screen/audio access. ScreenCaptureKit supplies system sound; MeetCue does not record screen images, and no virtual audio driver is needed. Microphone selection follows the system default unless you choose a specific device in Settings › Audio.</p><p>To try without keys, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/MeetCue.app/Contents/MacOS/MeetCue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --demo</span></span></code></pre></div><p>For the audio and shortcut checks, run the same executable with <code>--self-test</code>, with headphones connected, and speak during the microphone test. API keys use macOS Keychain. Updating replaces the app in Applications and keeps your settings and keys. To remove them, use <strong>Settings › General › Erase all data</strong>, then delete the app.</p><h2 id="install-with-scoop" tabindex="-1">Install with Scoop <a class="header-anchor" href="#install-with-scoop" aria-label="Permalink to &quot;Install with Scoop&quot;">​</a></h2><ol><li><p>If you don&#39;t have Scoop yet, open PowerShell and install it:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-ExecutionPolicy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy RemoteSigned </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope CurrentUser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm get.scoop.sh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div></li><li><p>Add the MeetCue bucket:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop bucket add meetcue https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Amazingkenneth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meetcue</span></span></code></pre></div></li><li><p>Install MeetCue:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop install meetcue</span></span></code></pre></div></li><li><p>Start <strong>MeetCue</strong> from the Start menu. The first-run setup opens; continue with <a href="/meetcue/setup">First-time setup</a>.</p></li></ol><h2 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop update meetcue</span></span></code></pre></div><p>Your settings, latency history and practice records are kept in Scoop&#39;s <code>persist</code> folder, and API keys stay in Windows Credential Manager, so updates keep everything.</p><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop uninstall meetcue</span></span></code></pre></div><p>To also remove your settings, add <code>--purge</code>. API keys remain in Windows Credential Manager under entries named <code>MeetCue</code>; remove them there if you want, or run <strong>Settings › General › Erase all data</strong> before uninstalling to remove keys and settings together.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>See <a href="/meetcue/troubleshooting/install">Install and upgrade troubleshooting</a>.</p>`,22)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
